using System; using System.IO; using System.Collections.Generic; using System.Security.Cryptography;
class ResidueFixtures {
 sealed class Registry:ISceneBlockRegistryStore {public string GetCommand(){return null;}public void SetCommand(string x){}public bool DeleteOwnedCommand(string x){return false;}}
 static void Check(bool ok,string text){if(!ok)throw new Exception(text);Console.WriteLine("PASS "+text);}
 static string Hash(string file){using(var sha=SHA256.Create())return BitConverter.ToString(sha.ComputeHash(File.ReadAllBytes(file))).Replace("-","").ToLowerInvariant();}
 static void Main(string[] args){try{Run(args[0]);}catch(Exception e){Console.WriteLine(e.Message);Environment.ExitCode=1;}}
 static void Run(string root){root=Path.GetFullPath(root);string workspace=Path.GetFullPath(Environment.CurrentDirectory)+Path.DirectorySeparatorChar;if(!root.StartsWith(workspace,StringComparison.OrdinalIgnoreCase)||Directory.Exists(root))throw new Exception("Fresh workspace fixture required");Directory.CreateDirectory(root);var known=new Dictionary<string,Dictionary<string,string>>();string folder=Path.Combine(root,"2.6.0");Directory.CreateDirectory(folder);var hashes=new Dictionary<string,string>();foreach(string n in new[]{"node.exe","2026-10-23-protocol.vbs","2026-10-23-on-demand.mjs"}){string f=Path.Combine(folder,n);File.WriteAllText(f,n);hashes[n]=Hash(f);}known["2.6.0"]=hashes;var m=new SceneBlockInstallationManager(root,"2.10.1",v=>false,new Registry(),known);File.Delete(Path.Combine(folder,"node.exe"));Check(m.Scan()[0].Recognized,"partial legacy remains recognized");Check(m.PlanRemoval(true).Files.Count==2,"only remaining matching official files planned");Directory.CreateDirectory(Path.Combine(folder,"2026-10-23-runtime"));File.WriteAllText(Path.Combine(folder,"2026-10-23-runtime","log.txt"),"keep");m.Remove(m.PlanRemoval(true));Check(m.Scan()[0].ResidualOnly&&!m.Scan()[0].ProgramFilesPresent,"runtime-only residue distinguished from installed program");Check(File.Exists(Path.Combine(folder,"2026-10-23-runtime","log.txt")),"runtime preserved");File.WriteAllText(Path.Combine(folder,"user.exe"),"unknown");Check(!m.Scan()[0].ResidualOnly&&m.Scan()[0].ProgramFilesPresent,"unknown executable never labelled removed");File.Delete(Path.Combine(folder,"user.exe"));File.WriteAllText(Path.Combine(folder,"2026-10-25-previous-protocol-202610250101.txt"),"keep backup");Check(m.Scan()[0].ResidualOnly,"protocol backup remains residue");File.WriteAllText(Path.Combine(folder,"settings.txt"),"unknown");Check(!m.Scan()[0].ResidualOnly,"unknown top-level file remains unverified");File.Delete(Path.Combine(folder,"settings.txt"));File.WriteAllText(Path.Combine(folder,"node.exe"),"modified");Check(!m.Scan()[0].Recognized&&m.Scan()[0].ProgramFilesPresent,"modified runtime not certified owned");Check(m.PlanRemoval(true).Files.Count==0,"modified and unknown files never selected");foreach(string n in hashes.Keys)File.WriteAllText(Path.Combine(folder,n),n);m.RecordManifest("2.6.0",hashes);foreach(string n in hashes.Keys)File.Delete(Path.Combine(folder,n));Check(m.Scan()[0].ResidualOnly,"manifest-only metadata is residue");Check(SceneBlockInstallationManager.StatusText(new SceneBlockVersionInfo{Registered=true}).Contains("등록 남음"),"orphaned registration is explicit");}
}
